/** Draft v2 values and their parsers; owner rules live in docs/business-rules.md. */
import { createHash } from 'node:crypto';
import { cleanText, exact, invalidImport, parseImportDate, record, uuid, type ImportDate, type ImportDecisionScopeV2, type ImportDuplicateDecision, type ImportManifest, type ImportSuggestion, type ImportValue } from './adminImportContract';
import { normalizeJoinPhrase } from '../../models/catalogCredit';
import { isPlaceholderCredit, normalizeMusicBrainzId } from '../lookup/lookupIdentifiers';
import type { AnalysisSuggestion } from './adminImportProvider';

export type ImportArtistEntry = { key: string; name: string; role: 'primary' | 'featured'; joinPhrase: string | null; musicBrainzId: string | null };
export type ImportLabelEntry = { name: string; musicBrainzId: string | null };
export type ImportDraftV2 = {
    album: { title: string; artists: ImportArtistEntry[]; label: ImportLabelEntry | null; releaseDate: ImportDate | null; visibility: 'public' | 'hidden' };
    tracks: { slotId: string; title: string; discNumber: number | null; trackNumber: number | null }[];
};
export type ImportValueOrigin = 'administrator' | 'automatic';
/** Keyed by the stored form of each value path (originKey); an absent path is the administrator's own. */
export type ImportDraftOrigins = Record<string, ImportValueOrigin>;
/**
 * The `draftOrigins` key of a value path, its dots replaced by colons (`album:title`, `tracks:<slotId>:discNumber`): MongoDB
 * before 5.0 refuses dotted field names in a replaced document, and the supported floor is 4.2.
 */
export const originKey = (path: string) => path.split('.').join(':');
export type ImportSuggestionV2 = Omit<ImportSuggestion, 'field' | 'baseline' | 'value'> & { field: 'title' | 'artists' | 'releaseDate' | 'trackNumber'; baseline: ImportValue | ImportArtistEntry[]; value: ImportValue | ImportArtistEntry[] };
/**
 * An Artist decision binds one entry by key and the name it was decided for; a label decision binds the label's name (entryKey
 * null); Album and track decisions bind neither. `preselected` is set only on a decision an approval froze because the review
 * preselected it (adminImportIdentity.ts); it is never a saved project decision, request item or DTO field.
 */
export type ImportDecisionV2 = Omit<ImportDuplicateDecision, 'scope'> & { scope: ImportDecisionScopeV2; entryKey: string | null; boundName: string | null; preselected?: true };

export const DRAFT_V2 = 2;
/** `decisions` is one per entry, the label, the Album and each of at most 100 tracks. */
export const DRAFT_V2_LIMITS = Object.freeze({ artists: 20, name: 200, title: 300, disc: 999, track: 9999, bytes: 48_000, decisions: 122 });

/** Empty Draft v2 of a draftless create: unknown numbers, no entries or label, and public visibility (owner rule). */
export const defaultDraftV2 = (manifest: ImportManifest): ImportDraftV2 => ({
    album: { title: '', artists: [], label: null, releaseDate: null, visibility: 'public' },
    tracks: manifest.files.map(file => ({ slotId: file.slotId, title: '', discNumber: null, trackNumber: null }))
});

/** Case-insensitive name identity: two Artist entries may not share a folded name. */
export const foldImportName = (value: string) => value.normalize('NFC').toLowerCase();
const canonical = (value: unknown): unknown => Array.isArray(value) ? value.map(canonical)
    : value && typeof value === 'object' ? Object.fromEntries(Object.keys(value).sort().map(key => [key, canonical((value as Record<string, unknown>)[key])])) : value;
/** Value equality independent of key order, as stored values and client bases are compared. */
export const sameDraftValue = (left: unknown, right: unknown) => JSON.stringify(canonical(left)) === JSON.stringify(canonical(right));
/**
 * Digest of what an approval confirmation shows from the saved project: its Draft v2 view, bound decisions (with the names they
 * were made for), selected cover, each staged asset's slot, state and bytes, and the "from file tags only" marks of the Artist
 * entries and the label. Key order never matters; actor, capabilities, receipts, revisions and analysis do not count.
 */
export const importApprovalDigest = (shown: { draft: ImportDraftV2; decisions: readonly unknown[]; selectedCoverSlotId: string | null;
    assets: readonly { slotId: string; state: string; sha256: string }[]; tagOnly: { artists: boolean; label: boolean } }): string =>
    createHash('sha256').update(JSON.stringify(canonical({ draft: shown.draft, decisions: shown.decisions, selectedCoverSlotId: shown.selectedCoverSlotId,
        assets: shown.assets.map(({ slotId, state, sha256 }) => ({ slotId, state, sha256 })), tagOnly: { artists: shown.tagOnly.artists, label: shown.tagOnly.label } }))).digest('hex');
/** Structural Draft v2 check: an Artist entry list and no v1 artistName. */
export const isDraftV2 = (value: unknown): value is ImportDraftV2 => {
    const draft = value as { album?: Record<string, unknown> } | null;
    return Boolean(draft && typeof draft === 'object' && draft.album && typeof draft.album === 'object' && Array.isArray(draft.album.artists) && !('artistName' in draft.album));
};
export const draftBytes = (draft: unknown) => Buffer.byteLength(JSON.stringify(draft));

/** Own-property test that a JSON body's prototype keys cannot satisfy. */
export const hasOwn = (value: object, key: string) => Object.prototype.hasOwnProperty.call(value, key);
/** Exact keys, every one present as an own property; anything else is invalid input. */
const exactly = (value: Record<string, unknown>, keys: string[]) => { exact(value, keys); if (keys.some(key => !hasOwn(value, key))) invalidImport(); };

/**
 * Text bounded before and after NFC: a few characters (such as U+0958) normalize to two code units, and a stored value over
 * its bound would drop out of the editor's allowlisted view.
 */
const normalizedText = (value: unknown, max: number, empty = false) => { const text = cleanText(value, max, empty); return text.length > max ? invalidImport() : text; };
/** Artist and label names: 1 to 200 characters after NFC and trimming, without control or invisible formatting characters. */
export function parseImportName(value: unknown): string {
    const name = normalizedText(value, DRAFT_V2_LIMITS.name);
    if (/[\p{Cc}\p{Cf}]/u.test(name)) return invalidImport();
    return name;
}
const parseJoinPhrase = (value: unknown): string | null => {
    if (value === null) return null;
    try { const phrase = normalizeJoinPhrase(value); return phrase === undefined ? invalidImport() : phrase; } catch { return invalidImport(); }
};
/** A client never introduces an ID: it may only keep the one stored for the same, unrenamed entry. */
const parseKeptMusicBrainzId = (value: unknown, stored: { name: string; musicBrainzId: string | null } | undefined, name: string): string | null => {
    if (value === null) return null;
    const id = normalizeMusicBrainzId(value);
    if (!id || !stored?.musicBrainzId || stored.musicBrainzId !== id || foldImportName(stored.name) !== foldImportName(name)) return invalidImport();
    return id;
};

/** Ordered Artist entries: unique keys and folded names, every primary before every featured entry, canonical key order. */
export function parseArtistEntries(value: unknown, stored: readonly ImportArtistEntry[]): ImportArtistEntry[] {
    if (!Array.isArray(value) || value.length > DRAFT_V2_LIMITS.artists) return invalidImport();
    const keys = new Set<string>(), names = new Set<string>(); let featured = false;
    return value.map(raw => {
        const entry = record(raw); exactly(entry, ['key', 'name', 'role', 'joinPhrase', 'musicBrainzId']);
        if (!uuid(entry.key) || keys.has(entry.key.toLowerCase())) return invalidImport();
        const key = entry.key.toLowerCase(), name = parseImportName(entry.name), folded = foldImportName(name), role = entry.role;
        if (names.has(folded) || (role !== 'primary' && role !== 'featured') || (role === 'primary' && featured)) return invalidImport();
        keys.add(key); names.add(folded); featured ||= role === 'featured';
        const joinPhrase = parseJoinPhrase(entry.joinPhrase), musicBrainzId = parseKeptMusicBrainzId(entry.musicBrainzId, stored.find(item => item.key === key), name);
        return { key, name, role, joinPhrase, musicBrainzId };
    });
}
/** No label, or exactly a name and a kept MusicBrainz ID. */
export function parseLabelEntry(value: unknown, stored: ImportLabelEntry | null): ImportLabelEntry | null {
    if (value === null) return null;
    const label = record(value); exactly(label, ['name', 'musicBrainzId']);
    const name = parseImportName(label.name);
    return { name, musicBrainzId: parseKeptMusicBrainzId(label.musicBrainzId, stored ?? undefined, name) };
}
const position = (max: number) => (value: unknown): number | null => {
    if (value === null) return null;
    return Number.isInteger(value) && (value as number) >= 1 && (value as number) <= max ? value as number : invalidImport();
};
export const parseDiscNumber = position(DRAFT_V2_LIMITS.disc);
export const parseTrackNumber = position(DRAFT_V2_LIMITS.track);
export const parseDraftTitle = (value: unknown) => normalizedText(value, DRAFT_V2_LIMITS.title, true);
export const parseDraftVisibility = (value: unknown): 'public' | 'hidden' => value === 'public' || value === 'hidden' ? value : invalidImport();

/** Complete exact Draft v2 parse with one track per manifest slot and the byte cap; per-path parsing follows the same rules. */
export function parseDraftV2(value: unknown, manifest: ImportManifest, stored?: ImportDraftV2): ImportDraftV2 {
    const input = record(value); exactly(input, ['album', 'tracks']);
    const album = record(input.album); exactly(album, ['title', 'artists', 'label', 'releaseDate', 'visibility']);
    if (!Array.isArray(input.tracks) || input.tracks.length !== manifest.files.length) return invalidImport();
    const seen = new Set<string>();
    const tracks = input.tracks.map(raw => {
        const track = record(raw); exactly(track, ['slotId', 'title', 'discNumber', 'trackNumber']);
        if (typeof track.slotId !== 'string' || !manifest.files.some(file => file.slotId === track.slotId) || seen.has(track.slotId)) return invalidImport();
        seen.add(track.slotId);
        return { slotId: track.slotId, title: parseDraftTitle(track.title), discNumber: parseDiscNumber(track.discNumber), trackNumber: parseTrackNumber(track.trackNumber) };
    });
    const result: ImportDraftV2 = {
        album: { title: parseDraftTitle(album.title), artists: parseArtistEntries(album.artists, stored?.album.artists ?? []), label: parseLabelEntry(album.label, stored?.album.label ?? null),
            releaseDate: parseImportDate(album.releaseDate), visibility: parseDraftVisibility(album.visibility) },
        tracks
    };
    return draftBytes(result) > DRAFT_V2_LIMITS.bytes ? invalidImport() : result;
}

/** A deterministic UUID-shaped key (version 4 and variant 8 nibbles) for an entry automation proposes. */
export function derivedEntryKey(seed: unknown): string {
    const hash = createHash('sha256').update(JSON.stringify(seed)).digest('hex');
    return `${hash.slice(0, 8)}-${hash.slice(8, 12)}-4${hash.slice(13, 16)}-8${hash.slice(17, 20)}-${hash.slice(20, 32)}`;
}

type Bindable = { scope: string };
const bindsEntry = (decision: Bindable, entry: ImportArtistEntry) =>
    (decision as Partial<ImportDecisionV2>).entryKey === entry.key && (decision as Partial<ImportDecisionV2>).boundName === entry.name;
const bindsLabel = (decision: Bindable, label: ImportLabelEntry | null) => label !== null && (decision as Partial<ImportDecisionV2>).boundName === label.name;
/**
 * Keeps every Album and track decision, each Artist decision whose entry still exists under the name it was decided for, and a
 * label decision while the label keeps the name it was decided for. Reordering an entry or changing its role or join phrase keeps
 * its decision; renaming or removing the entry or the label clears it.
 */
export const retainBoundDecisions = <T extends Bindable>(decisions: readonly T[], draft: ImportDraftV2): T[] =>
    decisions.filter(decision => decision.scope === 'artist' ? draft.album.artists.some(entry => bindsEntry(decision, entry))
        : decision.scope === 'label' ? bindsLabel(decision, draft.album.label) : true);
/** The artist decision bound to this entry, if any. */
export const boundArtistDecision = <T extends Bindable>(decisions: readonly T[], entry: ImportArtistEntry): T | undefined =>
    decisions.find(decision => decision.scope === 'artist' && bindsEntry(decision, entry));
/** The label decision bound to this label under its current name, if any. */
export const boundLabelDecision = <T extends Bindable>(decisions: readonly T[], label: ImportLabelEntry | null): T | undefined =>
    decisions.find(decision => decision.scope === 'label' && bindsLabel(decision, label));

/**
 * Maps one Luna suggestion onto Draft v2 until Luna proposes Draft v2 values (S15). Its baseline is the v2 baseline value at
 * the path. An artistName becomes a one-entry primary Artist suggestion that reuses the baseline's single entry key, or a
 * key derived from the seed; a name that fails the name rules, or a placeholder such as Various Artists (imports never suggest a
 * stand-in Artist), yields null (dropped).
 */
export function draftV2Suggestion(raw: AnalysisSuggestion, baseline: ImportDraftV2, seed: unknown): Omit<ImportSuggestionV2, 'id' | 'generation' | 'decision'> | null {
    const { scope, slotId, source, evidence } = raw;
    if (raw.field === 'artistName') {
        if (scope !== 'album') return null;
        let name: string; try { name = parseImportName(raw.value); } catch { return null; }
        if (isPlaceholderCredit(name)) return null;
        const current = baseline.album.artists, key = current.length === 1 ? current[0].key : derivedEntryKey(seed);
        return { scope, slotId, field: 'artists', baseline: structuredClone(current), value: [{ key, name, role: 'primary', joinPhrase: null, musicBrainzId: null }], source, evidence };
    }
    if (scope === 'album') {
        if (raw.field !== 'title' && raw.field !== 'releaseDate') return null;
        return { scope, slotId, field: raw.field, baseline: structuredClone(baseline.album[raw.field]), value: raw.value, source, evidence };
    }
    const track = baseline.tracks.find(item => item.slotId === slotId);
    if (!track || (raw.field !== 'title' && raw.field !== 'trackNumber')) return null;
    return { scope, slotId, field: raw.field, baseline: track[raw.field], value: raw.value, source, evidence };
}
